// Daten aus globalem Node-RED Kontext abfragen (mit Fallbacks)
let conn = global.get("shore_connected");
let p = global.get("shore_power");
let v = global.get("shore_voltage");
let i = global.get("shore_current");

// Typumwandlung und Plausibilität
let isConnected = (conn !== undefined) ? Boolean(conn) : false;
let power = (p !== undefined && !isNaN(Number(p))) ? Number(p) : 0;
let voltage = (v !== undefined && !isNaN(Number(v))) ? Number(v) : (isConnected ? 230.0 : 0.0);
let current = (i !== undefined && !isNaN(Number(i))) ? Number(i) : ((voltage > 10 && power > 0) ? +(power / voltage).toFixed(2) : 0.0);

// Wenn Leistung anliegt, gilt Landstrom automatisch als verbunden
if (power > 5.0) {
    isConnected = true;
    if (voltage < 50.0) voltage = 230.0;
}

msg.payload = {
    connected: isConnected,
    power: power,
    voltage: voltage,
    current: current
};

msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*"
};
return msg;

// Daten aus globalem Node-RED Kontext abfragen (mit Fallbacks)
let act = global.get("booster_active");
let p = global.get("booster_power");
let v = global.get("booster_voltage"); // z.B. Starterspannung / Lima-Spannung
let i = global.get("booster_current");

let isActive = (act !== undefined) ? Boolean(act) : false;
let power = (p !== undefined && !isNaN(Number(p))) ? Number(p) : 0;
let voltage = (v !== undefined && !isNaN(Number(v))) ? Number(v) : (isActive ? 14.2 : 0.0);
let current = (i !== undefined && !isNaN(Number(i))) ? Number(i) : 0.0;

// Wenn Ladeleistung > 5W anliegt, gilt Booster als aktiv
if (power > 5.0) {
    isActive = true;
}

msg.payload = {
    active: isActive,
    power: power,
    voltage: voltage,
    current: current
};

msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*"
};
return msg;

global.set("shore_connected", msg.payload.connected);
global.set("shore_power", msg.payload.power);
global.set("shore_voltage", msg.payload.voltage);
global.set("shore_current", msg.payload.current);
node.status({fill: msg.payload.connected ? "green" : "grey", shape: "dot", text: msg.payload.connected ? (msg.payload.power + " W") : "Aus"});
return msg;

global.set("booster_active", msg.payload.active);
global.set("booster_power", msg.payload.power);
global.set("booster_voltage", msg.payload.voltage);
global.set("booster_current", msg.payload.current);
node.status({fill: msg.payload.active ? "green" : "grey", shape: "dot", text: msg.payload.active ? (msg.payload.power + " W") : "Aus"});
return msg;

info:
Um echte Sensoren oder Shunts anzubinden, verbinde einfach die Ausgabe deiner Nodes (z.B. MQTT in, Shelly, Modbus, Victron GX) mit einer Function-Node oder Change-Node, die die globalen Variablen beschreibt:

1. Landstrom:
   global.set("shore_connected", boolean);
   global.set("shore_power", float_watt);
   global.set("shore_voltage", float_volt);
   global.set("shore_current", float_amp);

2. Ladebooster / Lichtmaschine:
   global.set("booster_active", boolean);
   global.set("booster_power", float_watt);
   global.set("booster_voltage", float_volt);
   global.set("booster_current", float_amp);

