// Beispiel: Eingehende Nachricht von Shelly MQTT oder HTTP (z.B. shellyplus1pm/status/switch:0)
// msg.payload = { "apower": 520.4, "voltage": 231.2, "current": 2.25, "output": true };

if (typeof msg.payload === "object" && msg.payload !== null) {
    let p = msg.payload.apower ?? msg.payload.power ?? 0;
    let v = msg.payload.voltage ?? 230.0;
    let i = msg.payload.current ?? (v > 0 ? p / v : 0);
    let conn = (msg.payload.output !== undefined) ? msg.payload.output : (p > 5.0 || v > 100.0);

    global.set("shore_connected", conn);
    global.set("shore_power", p);
    global.set("shore_voltage", v);
    global.set("shore_current", i);

    node.status({fill: conn ? "green" : "grey", shape: "dot", text: conn ? (p + " W") : "Aus"});
}
return msg;

// Beispiel: D+ GPIO Eingang (0 oder 1) oder Shunt/B2B Booster Leistung
// msg.payload = { "active": true, "power": 420.0, "starter_v": 14.1, "current": 30.0 };

if (typeof msg.payload === "object" && msg.payload !== null) {
    let act = msg.payload.active ?? (msg.payload.power > 5.0);
    let p = msg.payload.power ?? 0;
    let v = msg.payload.starter_v ?? msg.payload.voltage ?? 14.2;
    let i = msg.payload.current ?? (v > 0 ? p / v : 0);

    global.set("booster_active", act);
    global.set("booster_power", p);
    global.set("booster_voltage", v);
    global.set("booster_current", i);

    node.status({fill: act ? "green" : "grey", shape: "dot", text: act ? (p + " W") : "Aus"});
}
return msg;
